        emph_mark_types[n_emph_mark_types++] = _T('$');
    if(ctx->parser.flags & MD_FLAG_SPOILERS)
        emph_mark_types[n_emph_mark_types++] = _T('|');
    if(ctx->parser.flags & MD_FLAG_SUPERSCRIPTS)
        emph_mark_types[n_emph_mark_types++] = _T('^');
    if((ctx->parser.flags & MD_FLAG_STRIKETHROUGH) || (ctx->parser.flags & MD_FLAG_SUBSCRIPTS))
